CREATE   PROCEDURE
    inventar_SpcHidr.sp_guardar_contingencia_estado_operacional_test
(
    @FechaOperacional   date,
    @Turno              char(1),
    @EstadoOperacional  varchar(20),
    @Comentario         nvarchar(1000) = NULL,
    @Usuario            nvarchar(255)
)
AS
BEGIN

    SET NOCOUNT ON;
    SET XACT_ABORT ON;


    /* ============================================================
       NORMALIZACIÓN
       ============================================================ */

    DECLARE @TurnoNormalizado char(1);

    DECLARE @EstadoNormalizado varchar(20);

    DECLARE @UsuarioNormalizado nvarchar(255);

    DECLARE @ComentarioNormalizado nvarchar(1000);


    SET @TurnoNormalizado =
        UPPER(
            LTRIM(
                RTRIM(@Turno)
            )
        );


    SET @EstadoNormalizado =
        UPPER(
            LTRIM(
                RTRIM(@EstadoOperacional)
            )
        );


    SET @UsuarioNormalizado =
        LTRIM(
            RTRIM(@Usuario)
        );


    SET @ComentarioNormalizado =
        NULLIF(
            LTRIM(
                RTRIM(@Comentario)
            ),
            ''
        );


    /* ============================================================
       VALIDACIONES
       ============================================================ */

    IF @FechaOperacional IS NULL
        THROW 51101,
              'Debe informar @FechaOperacional.',
              1;


    IF @TurnoNormalizado NOT IN ('A', 'B')
        THROW 51102,
              '@Turno debe ser A o B.',
              1;


    IF @EstadoNormalizado NOT IN
    (
        'OPERATIVO',
        'MANTENCION',
        'CAIDA_PI'
    )
        THROW 51103,
              '@EstadoOperacional debe ser OPERATIVO, MANTENCION o CAIDA_PI.',
              1;


    IF @UsuarioNormalizado IS NULL
       OR LEN(@UsuarioNormalizado) = 0
        THROW 51104,
              'Debe informar @Usuario.',
              1;


    /* ============================================================
       INSERT APPEND-ONLY
       ============================================================ */

    INSERT INTO
        inventar_SpcHidr.contingencia_estado_operacional_test
    (
        fecha_operacional,
        turno,
        estado_operacional,
        comentario,
        usuario
    )

    OUTPUT
        inserted.id,
        inserted.fecha_operacional,
        inserted.turno,
        inserted.estado_operacional,
        inserted.comentario,
        inserted.usuario,
        inserted.fecha_registro

    VALUES
    (
        @FechaOperacional,
        @TurnoNormalizado,
        @EstadoNormalizado,
        @ComentarioNormalizado,
        @UsuarioNormalizado
    );

END;

CREATE   PROCEDURE
    inventar_SpcHidr.sp_registrar_contingencia_pi_test
(
    @FechaOperacional date,
    @Turno            char(1),
    @Accion           varchar(30),
    @Motivo           varchar(30) = NULL,
    @Comentario       nvarchar(1000) = NULL,
    @Usuario          nvarchar(255)
)
AS
BEGIN

    SET NOCOUNT ON;
    SET XACT_ABORT ON;


    DECLARE @TurnoN char(1) =
        UPPER(LTRIM(RTRIM(@Turno)));

    DECLARE @AccionN varchar(30) =
        UPPER(LTRIM(RTRIM(@Accion)));

    DECLARE @MotivoN varchar(30) =
        NULLIF(
            UPPER(LTRIM(RTRIM(@Motivo))),
            ''
        );

    DECLARE @ComentarioN nvarchar(1000) =
        NULLIF(
            LTRIM(RTRIM(@Comentario)),
            ''
        );

    DECLARE @UsuarioN nvarchar(255) =
        LTRIM(RTRIM(@Usuario));


    /* ============================================================
       VALIDACIONES BÁSICAS
       ============================================================ */

    IF @FechaOperacional IS NULL
        THROW 51201,
              'Debe informar @FechaOperacional.',
              1;


    IF @TurnoN NOT IN ('A','B')
        THROW 51202,
              '@Turno debe ser A o B.',
              1;


    IF @AccionN NOT IN
    (
        'ACTIVAR_CONTINGENCIA',
        'CERRAR_CONTINGENCIA'
    )
        THROW 51203,
              '@Accion debe ser ACTIVAR_CONTINGENCIA o CERRAR_CONTINGENCIA.',
              1;


    IF @UsuarioN IS NULL
       OR LEN(@UsuarioN) = 0
        THROW 51204,
              'Debe informar @Usuario.',
              1;


    IF @AccionN = 'ACTIVAR_CONTINGENCIA'
       AND @MotivoN NOT IN
       (
           'CAIDA_PI',
           'MANTENCION',
           'COMUNICACIONES',
           'SERVIDOR',
           'OTRO'
       )
        THROW 51205,
              'Debe informar un motivo válido para activar la contingencia.',
              1;


    IF @AccionN = 'CERRAR_CONTINGENCIA'
        SET @MotivoN = NULL;


    /* ============================================================
       ESTADO VIGENTE EN EL PUNTO OPERACIONAL SOLICITADO
       ============================================================ */

    DECLARE @UltimaAccion varchar(30);


    SELECT TOP (1)
        @UltimaAccion = a.accion

    FROM inventar_SpcHidr.contingencia_pi_accion_test AS a

    WHERE
        a.fecha_operacional < @FechaOperacional

        OR
        (
            a.fecha_operacional = @FechaOperacional
            AND
            CASE
                WHEN a.turno = 'A' THEN 1
                ELSE 2
            END
            <=
            CASE
                WHEN @TurnoN = 'A' THEN 1
                ELSE 2
            END
        )

    ORDER BY
        a.fecha_operacional DESC,

        CASE
            WHEN a.turno = 'A' THEN 1
            ELSE 2
        END DESC,

        a.fecha_registro DESC,
        a.id DESC;


    /* ============================================================
       CONTROL DE TRANSICIONES
       ============================================================ */

    IF @AccionN = 'ACTIVAR_CONTINGENCIA'
       AND @UltimaAccion = 'ACTIVAR_CONTINGENCIA'
        THROW 51206,
              'La contingencia PI ya se encuentra activa para ese periodo.',
              1;


    IF @AccionN = 'CERRAR_CONTINGENCIA'
       AND ISNULL(@UltimaAccion, 'NORMAL')
           <> 'ACTIVAR_CONTINGENCIA'
        THROW 51207,
              'No existe una contingencia PI activa para cerrar en ese periodo.',
              1;


    /* ============================================================
       INSERT APPEND-ONLY
       ============================================================ */

    INSERT INTO inventar_SpcHidr.contingencia_pi_accion_test
    (
        fecha_operacional,
        turno,
        accion,
        motivo,
        comentario,
        usuario
    )

    OUTPUT
        inserted.id,
        inserted.fecha_operacional,
        inserted.turno,
        inserted.accion,
        inserted.motivo,
        inserted.comentario,
        inserted.usuario,
        inserted.fecha_registro

    VALUES
    (
        @FechaOperacional,
        @TurnoN,
        @AccionN,
        @MotivoN,
        @ComentarioN,
        @UsuarioN
    );

END;
